<?php use Tecnodata\Lms\Core\Csrf; ?><div class="page-heading"><div><span class="eyebrow">CURSO</span><h1><?=e($enrollment['name'])?></h1><div class="progress-track wide"><span style="width:<?=$enrollment['progress_percent']?>%"></span></div><small><?=$enrollment['progress_percent']?>% concluído</small></div><a class="btn btn-outline-secondary" href="/student">Meus cursos</a></div><div class="learning-list"><?php foreach($sections as $s):?><section><h2><?=e($s['title'])?></h2><?php foreach($s['activities'] as $a):$data=json_decode($a['content_json']?:'{}',true)?:[];?><article class="learning-item <?=$a['completed']?'done':''?>"><div class="activity-icon"><i class="bi <?=$a['completed']?'bi-check-lg':($a['type']==='video'?'bi-play-fill':'bi-file-earmark-text')?>"></i></div><div class="flex-grow-1"><strong><?=e($a['title'])?></strong><small><?=e($a['type'])?></small><?php if($a['type']==='video' && !empty($data['url'])):?><a class="d-block mt-2" target="_blank" rel="noopener" href="<?=e($data['url'])?>">Abrir vídeo</a><?php elseif($a['type']==='page' && !empty($data['html'])):?><div class="activity-preview"><?=strip_tags($data['html'],'<p><strong><em><ul><ol><li><br>')?></div><?php endif;?></div><?php if(!$a['completed']):?><form method="post" action="/student/activity/<?=$a['id']?>/complete"><?=Csrf::field()?><input type="hidden" name="enrollment_id" value="<?=$enrollment['id']?>"><button class="btn btn-sm btn-brand">Concluir</button></form><?php else:?><span class="text-success fw-semibold">Concluído</span><?php endif;?></article><?php endforeach;?></section><?php endforeach;?></div>